namespace CubeAntivirus.Core; public sealed class HashDatabase { private readonly HashSet<string> _hashes = new(StringComparer.OrdinalIgnoreCase); public bool Contains(string hash) => _hashes.Contains(hash); public void Add(string hash) { if (hash.Length != 64 || !hash.All(Uri.IsHexDigit)) throw new ArgumentException("Expected a SHA-256 hex digest.", nameof(hash)); _hashes.Add(hash); } }